SELECT u.*, COUNT(t.id) as ticket_count FROM users u LEFT JOIN tickets t ON t.author_id = u.id WHERE 1=1
AND u.email LIKE '%' || #{emailKeyword} || '%'
AND u.sign_up_time >= #{registerDateFrom}
AND u.sign_up_time <= #{registerDateTo}
GROUP BY u.id ORDER BY ${sortBy} DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM users WHERE 1=1
AND email LIKE '%' || #{emailKeyword} || '%'
AND sign_up_time >= #{registerDateFrom}
AND sign_up_time <= #{registerDateTo}
